package com.nigson.acceptance.reward;
import java.net.*;import java.net.http.*;import java.time.*;import java.util.*;
import org.springframework.context.ConfigurableApplicationContext;import org.springframework.jdbc.core.JdbcTemplate;
import com.nigson.commerce.party.*;import com.nigson.commerce.security.*;import com.nigson.shared.events.EventCodec;
import static org.assertj.core.api.Assertions.*;
public final class RewardHttpAcceptance {
 private RewardHttpAcceptance(){}
 public static void run(ConfigurableApplicationContext app,HttpClient http,String base)throws Exception{
  JdbcTemplate jdbc=app.getBean(JdbcTemplate.class);PartyService parties=app.getBean(PartyService.class);JdbcSessionTrust sessions=app.getBean(JdbcSessionTrust.class);String issuer="http://127.0.0.1:9/realms/offline";List<UUID> ids=new ArrayList<>();UUID market=UUID.randomUUID(),rule=UUID.randomUUID();boolean[] createdMarket={false},marketEnabledBefore={false};Map<UUID,String> cookies=new HashMap<>(),csrf=new HashMap<>();
  try{
   for(int i=0;i<2;i++){String subject=UUID.randomUUID().toString();UUID id=parties.provision(new PartyValues.VerifiedIdentity(issuer,subject,subject+"@example.invalid",true,"Synthetic reward customer"));ids.add(id);var flow=sessions.begin("/account");sessions.consume(flow.sessionId(),flow.flow().state());String token=JdbcSessionTrust.opaque();csrf.put(id,token);cookies.put(id,"__Host-nigson-session="+sessions.authenticate(flow.sessionId(),new SessionRecord(1,id,issuer,subject,Instant.now(),null,"synthetic-access","synthetic-refresh",Instant.now().plusSeconds(300),token,SessionRecord.TokenState.READY)));}
   jdbc.update("INSERT INTO commerce.currency(id,created_by,updated_by,code,minor_unit) VALUES (?,'test','test','NGN',2) ON CONFLICT(code) DO NOTHING",UUID.randomUUID());var markets=jdbc.query("SELECT id,enabled FROM commerce.market WHERE code='NG'",(r,n)->new Object[]{r.getObject(1,UUID.class),r.getBoolean(2)});if(markets.isEmpty()){jdbc.update("INSERT INTO commerce.market(id,created_by,updated_by,code,name,currency_code,enabled) VALUES (?,'test','test','NG','Synthetic reward market','NGN',true)",market);createdMarket[0]=true;}else{market=(UUID)markets.getFirst()[0];marketEnabledBefore[0]=(Boolean)markets.getFirst()[1];if(!marketEnabledBefore[0])jdbc.update("UPDATE commerce.market SET enabled=true WHERE id=?",market);}
   String parameters="{\"schemaVersion\":1,\"minimumSettledSpend\":\"0.00\",\"referrerReward\":\"25.00\",\"referredReward\":\"5.00\",\"holdDays\":0,\"expiresDays\":365,\"maximumRewardsPerReferrer\":10,\"refundMode\":\"PROPORTIONAL\"}";
   jdbc.update("INSERT INTO commerce.promotion_rule(id,created_by,updated_by,code,revision,kind,market_id,starts_at,ends_at,parameters,eligibility,stacking_policy,enabled) VALUES (?,'test','test',?,1,'REFERRAL',?,now()-interval '1 hour',now()+interval '1 day',?::jsonb,'{}'::jsonb,'STACKABLE',true)",rule,"HTTP_REFERRAL_"+rule.toString().replace("-","").substring(0,12),market,parameters);
   String root=base+"/api/v1/me",rewards=root+"/rewards",referral=root+"/referral-code",attribution=root+"/referral-attribution";UUID first=ids.get(0),second=ids.get(1);String firstCookie=cookies.get(first),secondCookie=cookies.get(second);
   assertThat(send(http,HttpRequest.newBuilder(URI.create(rewards)).GET()).statusCode()).isEqualTo(401);assertThat(EventCodec.JSON.readTree(send(http,request(rewards,firstCookie).GET()).body()).path("entries")).isEmpty();assertThat(send(http,request(referral,firstCookie).GET()).statusCode()).isEqualTo(404);
   String createKey=UUID.randomUUID().toString();var codeResponse=send(http,mutation(referral,firstCookie,csrf.get(first),createKey,"{}"));assertThat(codeResponse.statusCode()).isEqualTo(201);String code=EventCodec.JSON.readTree(codeResponse.body()).path("code").asString();assertThat(code).matches("[A-Z0-9]{16,60}");assertThat(EventCodec.JSON.readTree(codeResponse.body()).path("link").asString()).isEqualTo("https://shop.synthetic.test/referrals/"+code);assertThat(send(http,mutation(referral,firstCookie,csrf.get(first),createKey,"{}")).body()).isEqualTo(codeResponse.body());assertThat(send(http,mutation(referral,firstCookie,csrf.get(first),UUID.randomUUID().toString(),"{}")).body()).isEqualTo(codeResponse.body());assertThat(send(http,request(referral,firstCookie).GET()).body()).isEqualTo(codeResponse.body());
   assertThat(send(http,mutation(attribution,firstCookie,csrf.get(first),UUID.randomUUID().toString(),"{\"code\":\""+code+"\"}")).statusCode()).isEqualTo(422);String attributionKey=UUID.randomUUID().toString();var attributed=send(http,mutation(attribution,secondCookie,csrf.get(second),attributionKey,"{\"code\":\""+code+"\"}"));assertThat(attributed.statusCode()).isEqualTo(201);assertThat(EventCodec.JSON.readTree(attributed.body()).path("state").asString()).isEqualTo("ATTRIBUTED");assertThat(send(http,mutation(attribution,secondCookie,csrf.get(second),attributionKey,"{\"code\":\""+code+"\"}")).body()).isEqualTo(attributed.body());assertThat(send(http,mutation(attribution,secondCookie,csrf.get(second),UUID.randomUUID().toString(),"{\"code\":\""+code+"\"}")).statusCode()).isEqualTo(422);
   jdbc.update("INSERT INTO commerce.reward_entry(id,created_by,party_id,rule_id,kind,amount,currency_code,business_key) VALUES (?,'test',?,?,'EARN',100.00,'NGN',?)",UUID.randomUUID(),first,rule,"reward-http-earn-"+UUID.randomUUID());jdbc.update("INSERT INTO commerce.reward_entry(id,created_by,party_id,rule_id,kind,amount,currency_code,business_key) VALUES (?,'test',?,?,'REDEEM',10.00,'NGN',?)",UUID.randomUUID(),first,rule,"reward-http-redeem-"+UUID.randomUUID());jdbc.update("INSERT INTO commerce.reward_entry(id,created_by,party_id,rule_id,kind,amount,currency_code,business_key,expires_at) VALUES (?,'test',?,?,'EARN',1000.00,'NGN',?,now()-interval '1 day')",UUID.randomUUID(),first,rule,"reward-http-expired-"+UUID.randomUUID());jdbc.update("INSERT INTO commerce.reward_entry(id,created_by,party_id,rule_id,kind,amount,currency_code,business_key) VALUES (?,'test',?,?,'EARN',500.00,'NGN',?)",UUID.randomUUID(),second,rule,"reward-http-foreign-"+UUID.randomUUID());var ledger=EventCodec.JSON.readTree(send(http,request(rewards,firstCookie).GET()).body());assertThat(ledger.path("availableByCurrency").get(0).path("amount").asString()).isEqualTo("90.00");assertThat(ledger.path("entries").size()).isEqualTo(3);var other=send(http,request(rewards,secondCookie).GET()).body();assertThat(other).contains("500.00").doesNotContain("100.00");assertThat(send(http,request(rewards+"?partyId="+second,firstCookie).GET()).statusCode()).isEqualTo(400);
  }finally{var bootstrap=new JdbcTemplate(new org.springframework.jdbc.datasource.DriverManagerDataSource(System.getenv("NIGSON_TEST_JDBC_URL"),"nigson_bootstrap","mock-bootstrap"));for(UUID id:ids){sessions.revokeSubject(id);bootstrap.update("DELETE FROM commerce.reward_entry WHERE party_id=?",id);jdbc.update("DELETE FROM commerce.referral_attribution WHERE referrer_party_id=? OR referred_party_id=?",id,id);jdbc.update("DELETE FROM commerce.referral_code WHERE party_id=?",id);}jdbc.update("DELETE FROM commerce.promotion_rule WHERE id=?",rule);if(createdMarket[0])jdbc.update("DELETE FROM commerce.market WHERE id=?",market);else jdbc.update("UPDATE commerce.market SET enabled=? WHERE id=?",marketEnabledBefore[0],market);for(UUID id:ids){jdbc.update("DELETE FROM commerce.customer_profile WHERE party_id=?",id);jdbc.update("DELETE FROM commerce.party WHERE id=?",id);}}
 }
 private static HttpRequest.Builder request(String url,String cookie){return HttpRequest.newBuilder(URI.create(url)).header("Cookie",cookie);}
 private static HttpRequest.Builder mutation(String url,String cookie,String csrf,String key,String body){return request(url,cookie).header("Idempotency-Key",key).header("X-CSRF-TOKEN",csrf).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body));}
 private static HttpResponse<String> send(HttpClient http,HttpRequest.Builder request)throws Exception{return http.send(request.timeout(Duration.ofSeconds(5)).build(),HttpResponse.BodyHandlers.ofString());}
}
